"""Generate out/w4-rB.workflow.json from Brief A + Brief B (multi-product) rules."""
import json, sys

BASE = "https://freya-bank-mock.freyavoice.workers.dev/v1"
HOLIDAYS = ["2026-10-26", "2026-11-11", "2026-11-26", "2026-12-25", "2027-01-01"]
EARLY_BD, LATE_BD = 12, 7          # memo 2026-10-09 overrides 10 / 5
EARLY_ATTEMPTS, LATE_ATTEMPTS = 1, 2
PROMISE_FAIL_LIMIT = 2             # Brief B memo: 2 failed calls per product


def body_tool(name, desc, fields, required, mapping=None, pre=None, post=None, read=False):
    props = {"customer_id": {"type": "string", "default": "{{customer_id}}"}}
    props.update(fields)
    t = {
        "type": "function",
        "config": {"timeoutMs": 12000, "maxRetries": 2 if read else 0},
        "function": {
            "name": name,
            "handler": "__function__:api_call",
            "description": desc,
            "parameters": {"type": "object", "properties": {
                "url": {"type": "string", "default": f"{BASE}/{name}"},
                "method": {"type": "string", "default": "POST"},
                "headers": {"type": "object", "properties": {"Content-Type": {"type": "string", "default": "application/json"}}},
                "body": {"type": "object", "properties": props, "required": required},
            }},
        },
    }
    if mapping:
        t["response_mapping"] = mapping
    if pre:
        t["pre_process_code"] = pre
    if post:
        t["post_process_code"] = post
    return t


def f_str(desc, default, enum=None):
    d = {"type": "string", "description": desc, "default": default}
    if enum:
        d["enum"] = enum
    return d

