CAL_HELPERS = r'''
import datetime, json
HOL = __HOL__
WD = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday']
ONE = datetime.timedelta(days=1)
def isbd(d):
    return d.weekday() < 5 and d.isoformat() not in HOL
def add_bd(d, n):
    x = d
    c = 0
    while c < n:
        x = x + ONE
        if isbd(x):
            c += 1
    return x
def next_bd(d):
    x = d + ONE
    while not isbd(x):
        x = x + ONE
    return x
def on_or_next_bd(d):
    x = d
    while not isbd(x):
        x = x + ONE
    return x
def last_bd_of_week(d):
    mon = d - datetime.timedelta(days=d.weekday())
    x = mon + datetime.timedelta(days=4)
    while x >= mon and not isbd(x):
        x = x - ONE
    return x if x >= mon else None
def fmtd(d):
    return d.isoformat() + ' (' + WD[d.weekday()] + ')'
raw_now = str(vars.get('now') or '').strip().replace(' ', 'T')
try:
    NOW = datetime.datetime.fromisoformat(raw_now[:16])
except Exception:
    try:
        NOW = datetime.datetime.fromisoformat(raw_now[:10] + 'T11:00')
    except Exception:
        NOW = datetime.datetime(2026, 10, 14, 11, 0)
TODAY = NOW.date()
lbw = last_bd_of_week(TODAY)
if lbw is None or lbw <= TODAY:
    lbw = last_bd_of_week(TODAY + datetime.timedelta(days=7))
ATTEMPT1_DATE = lbw
EARLY_DL = add_bd(TODAY, __EARLY__)
LATE_DL = add_bd(TODAY, __LATE__)
'''.replace("__HOL__", repr(HOLIDAYS)).replace("__EARLY__", str(EARLY_BD)).replace("__LATE__", str(LATE_BD))

SETUP_CODE = CAL_HELPERS + r'''
try:
    lines = []
    lines.append('Today is ' + fmtd(TODAY) + ', time ' + NOW.strftime('%H:%M') + ('. Today is a business day.' if isbd(TODAY) else '. Today is NOT a business day.'))
    lines.append('Business days are Monday to Friday, except Freya Bank holidays: ' + ', '.join(HOL) + '.')
    lines.append('Next business day: ' + fmtd(next_bd(TODAY)) + '.')
    lines.append('Last business day of this week (or of next week if today is that day): ' + fmtd(ATTEMPT1_DATE) + '.')
    mon = TODAY - datetime.timedelta(days=TODAY.weekday())
