    for i in range(7):
        a = mon + datetime.timedelta(days=i)
        b = a + datetime.timedelta(days=7)
        tn.append('"this ' + WD[i] + '" = ' + a.isoformat() + (' (already past)' if a < TODAY else '') + ', "next ' + WD[i] + '" = ' + b.isoformat())
    lines.append('Weekday words: ' + '; '.join(tn) + '.')
    cal = []
    end = max(EARLY_DL, LATE_DL) + datetime.timedelta(days=10)
    d = TODAY
    while d <= end:
        if isbd(d):
            st = 'business day'
