            st = 'HOLIDAY, not a business day'
        else:
            st = 'weekend, not a business day'
        cal.append(fmtd(d) + (' today' if d == TODAY else '') + ': ' + st)
        d = d + ONE
    lines.append('Calendar:\n' + '\n'.join(cal))
    vars['date_facts'] = '\n'.join(lines)
    cb = []
    nb = next_bd(TODAY)
    if NOW.hour < 19:
