except Exception as e:
    vars['date_facts'] = 'Date facts unavailable. Now is ' + str(vars.get('now'))
    vars['callback_window'] = 'Today or the next business day, from 10:00 to 19:00, later than now.'
    vars['today_iso'] = str(vars.get('now'))[:10]
    vars['today_text'] = str(vars.get('now'))
    vars['setup_state'] = 'error'
'''

PLAN_CODE = CAL_HELPERS + r'''
import re
try:
    import ast
except Exception:
    ast = None
def parse_products():
    cands = [vars.get('account_products'), vars.get('load_account_response.data.products'), vars.get('get_account_response.data.products')]
    for c in cands:
        if isinstance(c, list) and c:
            return c
        if isinstance(c, str) and c.strip():
            try:
                x = json.loads(c)
                if isinstance(x, list) and x:
                    return x
            except Exception:
                pass
            if ast is not None:
                try:
                    x = ast.literal_eval(c)
                    if isinstance(x, list) and x:
                        return x
                except Exception:
                    pass
    found = dict()
    for k, val in list(vars.items()):
        m = re.search(r'products\.(\d+)\.(\w+)$', str(k))
        if m:
            found.setdefault(int(m.group(1)), dict())[m.group(2)] = val
    return [found[i] for i in sorted(found)]
def num(x):
    try:
        return float(x)
    except Exception:
        return 0.0
def money(x):
    x = num(x)
    if abs(x - round(x)) < 0.005:
        return '{:,}'.format(int(round(x)))
    return '{:,.2f}'.format(x)
try:
    prods = [p for p in parse_products() if isinstance(p, dict)]
    facts = []
    sentences = []
    order = []
    for i, p in enumerate(prods):
        pid = str(p.get('product_id') or '')
        order.append(pid)
        typ = str(p.get('type') or '')
        if typ == 'credit_card':
            words = 'credit card ending ' + str(p.get('card_last4') or '')
            floor = num(p.get('minimum_payment'))
            floor_name = 'minimum payment'
        elif typ == 'car_loan':
            words = 'car loan'
            floor = num(p.get('instalment_amount'))
            floor_name = 'instalment amount'
        else:
            words = 'personal loan'
            floor = num(p.get('instalment_amount'))
            floor_name = 'instalment amount'
        past = num(p.get('past_due'))
        dl = 0
        try:
            dl = int(float(p.get('days_late')))
        except Exception:
            dl = 0
        if dl <= 7:
            band = 'early band (1-7 days late)'
            deadline = EARLY_DL
            attempts = __EA__
        else:
            band = 'late band (8-45 days late)'
            deadline = LATE_DL
            attempts = __LA__
        valid = []
        d = TODAY
        while d <= deadline:
            if isbd(d):
                valid.append(d.isoformat())
            d = d + ONE
        a1 = ATTEMPT1_DATE if ATTEMPT1_DATE <= deadline else deadline
        f = []
        f.append('PRODUCT ' + str(i + 1) + ': "' + words + '"')
        f.append('  product_id: ' + pid + '  (copy exactly into create_promise / add_note)')
        f.append('  past-due amount (full amount): ' + money(past))
        f.append('  days late: ' + str(dl) + ' -> ' + band)
        f.append('  floor (' + floor_name + '): ' + money(floor) + '. Acceptable amounts: from ' + money(floor) + ' to ' + money(past) + ' inclusive.')
        f.append('  deadline (latest promise date): ' + fmtd(deadline))
        f.append('  allowed promise dates (business days from today to the deadline): ' + ', '.join(valid))
        f.append('  persuasion attempts available: ' + str(attempts))
        f.append('  attempt 1 offer: ' + money(past) + ' (or the floor ' + money(floor) + ' if the customer already said the full amount is too much) on ' + fmtd(a1))
        if attempts >= 2:
            f.append('  attempt 2 offer: the floor ' + money(floor) + ' on the deadline ' + fmtd(deadline))
        else:
            f.append('  no attempt 2 for this product (early band).')
        facts.append('\n'.join(f))
        sentences.append('Your ' + words + ' has ' + money(past) + ' past due and is ' + str(dl) + ' days late.')
    if prods:
        if len(prods) == 1:
            dis = ('Thank you, you are verified. I am calling from the collections team about a late payment. ' + sentences[0] +
                   ' Can you make this payment today?')
        else:
            dis = ('Thank you, you are verified. I am calling from the collections team about late payments on ' + str(len(prods)) + ' products. ' +
                   ' '.join(sentences) + ' Can you pay all of them today?')
        vars['products_facts'] = '\n\n'.join(facts)
        vars['disclosure_text'] = dis
        vars['product_count'] = len(prods)
        vars['product_order_json'] = json.dumps(order)
        vars['product_order_text'] = ', '.join(order)
        vars['plan_state'] = 'ready'
    else:
        vars['plan_state'] = 'error'
        vars['products_facts'] = 'No account data.'
        vars['disclosure_text'] = ''
except Exception as e:
    vars['plan_state'] = 'error'
    vars['products_facts'] = 'No account data.'
    vars['disclosure_text'] = ''
'''.replace("__EA__", str(EARLY_ATTEMPTS)).replace("__LA__", str(LATE_ATTEMPTS))

for c in (SETUP_CODE, PLAN_CODE):
    assert "{{" not in c and "}}" not in c

# ---------------------------------------------------------------- tools
TOOL_RULE = ("After every tool result read `tool_outcome` first. If it starts with FAILED, nothing was recorded: never say it "
             "was recorded, booked or done. If the result has `what_to_do_next`, follow it. Call one tool per message. After every "
             "tool result, speak to the customer or call the next tool; never end a turn with nothing. Never announce that something "
             "is recorded, booked, scheduled, transferred or sent before its tool result shows SUCCESS.")

def verify_tool():
    return body_tool(
        "verify_identity",
        "Check ONE security answer. CALL it every time the customer answers a security question (date of birth first, then the last four digits of the phone number on file).",
        {"field": f_str("Which question this answer is for: date_of_birth or phone_last4.", "{{field}}", ["date_of_birth", "phone_last4"]),
         "answer": f_str("date_of_birth: the date as YYYY-MM-DD (a date said only in numbers is day, then month, then year). phone_last4: exactly four digits.", "{{answer}}")},
        ["field", "answer"], post=VERIFY_POST)


def promise_tool():
    return body_tool(
        "create_promise",
        "Record ONE confirmed payment promise for ONE product. CALL it only after the customer gave a clear yes to the read-back, once per confirmed product. Never twice for a product already recorded.",
        {"product_id": f_str("product_id of the product, copied exactly from the product list (" + "known ids: {{product_order_text}}" + ").", "{{product_id}}"),
         "amount": {"type": "number", "description": "Confirmed amount, a number without currency.", "default": "{{amount}}"},
         "date": f_str("Confirmed payment date as YYYY-MM-DD.", "{{date}}")},
        ["product_id", "amount", "date"], pre=PROMISE_PRE, post=PROMISE_POST)


def note_tool():
    return body_tool(
        "add_note",
        "Record why ONE product ended without a promise. CALL it once for each product that has no recorded promise, after all create_promise calls, before close_call. Never after or around a transfer.",
        {"product_id": f_str("product_id copied exactly from the product list.", "{{product_id}}"),
         "reason": f_str("refused, hardship, dispute, paid or service_error.", "{{reason}}", ["refused", "hardship", "dispute", "paid", "service_error"])},
        ["product_id", "reason"], pre=NOTE_PRE, post=NOTE_POST)


def transfer_tool(queues):
    return body_tool(
        "transfer_to_agent",
        "Hand the call to a person. CALL it only when the rules say to transfer: restructuring = customer asks for a new payment plan or lower instalments; support = hardship customer accepted the support team; general = customer insists on a human after one offer to help.",
        {"queue": f_str("One of: " + ", ".join(queues) + ".", "{{queue}}", queues)},
        ["queue"], pre=TRANSFER_PRE, post=TRANSFER_POST)


def callback_tool():
    return body_tool(
        "schedule_callback",
        "Book a callback for the customer. CALL it when the person answering gives a day and time inside the allowed window.",
        {"date": f_str("Callback date, YYYY-MM-DD.", "{{date}}"),
         "time": f_str("Callback time, HH:MM, 24 hour.", "{{time}}")},
        ["date", "time"], post=CALLBACK_POST)


def close_tool(outcome, reason, outcome_enum=None, reason_enum=None, desc_extra=""):
    fields = {"outcome": f_str("Call outcome." + (" One of: " + ", ".join(outcome_enum) + "." if outcome_enum else ""), outcome, outcome_enum)}
    if reason is not None:
        fields["reason"] = f_str("Reason." + (" One of: " + ", ".join(reason_enum) + "." if reason_enum else "") + " Leave empty for promise and paid.", reason, reason_enum)
    return body_tool(
        "close_call",
        "End the call record. CALL it exactly once, as the very last tool call, in the same message in which you thank the customer and say goodbye. " + desc_extra,
        fields, ["outcome"], pre=CLOSE_PRE, post=CLOSE_POST)

# ---------------------------------------------------------------- transitions
def cond_or(*cs):
    return {"logic": "or", "conditions": list(cs)}

def eq(var, val):
    return {"variable": var, "operator": "equals", "operand": val}

def is_true(var):
    return [eq(var, "true"), eq(var, "True")]

def tr(target, desc, cond):
    return {"target_node": target, "description": desc, "condition": cond}

T_CLOSED = tr("end", "close_call succeeded", cond_or(eq("call_closed", "yes"), *is_true("close_call_response.data.ok")))
T_TRANSFERRED = tr("after_transfer", "transfer succeeded", cond_or({"variable": "transfer_reason", "operator": "is_set"}))

def conv(name, task, tools, transitions, on_enter=None, extraction=None, max_turns=30, max_target="end", first_only=True):
    n = {"name": name, "node_type": "conversation", "task_message": task, "tools": tools, "transitions": transitions,
         "on_enter": on_enter or {"type": "llm"}, "on_enter_first_entry_only": first_only,
         "max_node_turns": max_turns, "max_turn_transition": max_target}
    if extraction:
        n["extraction_schema"] = extraction
    return n

def code_node(name, code, nxt_transitions, default):
    return {"name": name, "node_type": "code", "passthrough": True, "passthrough_default_transition": default,
            "on_enter": {"type": "silent"}, "disable_inactivity_monitor": True,
            "pre_actions": [{"type": "function", "function": {"name": "code_exec", "handler": "__function__:code_exec",
                             "parameters": {"type": "object", "properties": {"code": {"type": "string", "default": code},
                                                                              "timeout_ms": {"type": "number", "default": 10000}}}}}],
            "transitions": nxt_transitions}

# ---------------------------------------------------------------- prompts
SYSTEM = f"""You are Freya Bank's digital assistant on an outbound phone call to {{{{title}}}} {{{{first_name}}}} {{{{last_name}}}}. Freya Bank is fictional; all data is synthetic. Speak English. Keep every turn to one or two short sentences. Address the customer as {{{{title}}}} {{{{last_name}}}}.

Rules in every step:
- The current date and time is {{{{now}}}}. Use only this for every date; never use the real clock.
- Until both security questions have passed, never say "collections", "debt", "payment", any amount or any product, to anyone, including relatives. If asked what the call is about before that, say you can explain only to {{{{title}}}} {{{{last_name}}}} after a short security check.
- If asked whether you are a robot or an AI: say you are Freya Bank's digital assistant, then continue.
- If asked "Is this a scam?" or similar: say they can verify this call by phoning Freya Bank's customer service number, then continue.
- If a question cannot be answered from the information you have, say you do not have that information. Never invent figures, dates or reasons.
- Never offer a discount, waiver, instalment plan or any term that the rules here do not give you.
- Never give account information to anyone other than the verified customer.
- {TOOL_RULE}
- When you end the call: thank the customer and say goodbye, and call close_call in that same message. close_call is always the last tool call."""

OPENING_TASK = """You are confirming that you are speaking with {{title}} {{last_name}}. No account information may be given.
- Only "yes", "that's me", "speaking" or the customer's own name confirm. "Hello", "go ahead", "who is this" or a question do NOT confirm.
- If the answer is unclear, ask once more exactly: "Am I speaking with {{title}} {{last_name}}?". If the person asks a question, answer it first (you are Freya Bank's digital assistant; for a scam question, they can phone Freya Bank's customer service number to verify the call), then ask again; that ask is the second ask.
- If it is still unclear after the second ask: thank them, say goodbye and call close_call (outcome not_reached, reason unclear) in the same message.
- Do not ask security questions here and do not call any tool except close_call in the unclear case."""

THIRD_PARTY_TASK = """The person on the line is NOT {{title}} {{last_name}} (or says the number is wrong, or that the customer has died). Never say why you are calling and say nothing about any account, debt or payment, even if they ask or offer to pay. A relative can never answer security questions.

Callback window: {{callback_window}}

{{date_facts}}

Handle exactly one of these:
- The customer has died: say exactly "I am sorry for your loss.", ask nothing else, thank them, say goodbye and call close_call with reason deceased.
- The number does not belong to the customer (wrong number): apologise briefly, thank them, say goodbye and call close_call with reason wrong_number.
- Otherwise ask when {{title}} {{last_name}} can be reached. Convert what they say to a date and time using the calendar above.
  * Inside the window: call schedule_callback with date (YYYY-MM-DD) and time (HH:MM). Only after its result shows success say the callback is booked; then thank them, say goodbye and call close_call with reason callback.
  * Outside the window (first time): say that time is not possible and ask once for another time today or the next business day between 10:00 and 19:00.
  * Outside the window again: do not book anything; thank them, say goodbye and call close_call with reason no_callback.
  * If schedule_callback FAILED: try once more with the same values. If it fails again, say the callback could not be booked, thank them, say goodbye and call close_call with reason no_callback.
  * If they will not give any time: thank them, say goodbye and call close_call with reason no_callback.
close_call outcome is always not_reached here."""

VERIFY_TASK = """{{title}} {{last_name}} has confirmed who they are. Now do the security check. Do not mention any account information, debt, payment, amount or product yet.
1. Ask for their date of birth. When they answer, call verify_identity with field date_of_birth and answer as YYYY-MM-DD, however they said it. A date said only in numbers is day, then month, then year (05/03/1980 = 1980-03-05). Words: "fifth of March nineteen eighty" = 1980-03-05.
2. When the date of birth has passed, ask for the last four digits of the phone number on file and call verify_identity with field phone_last4 and the four digits.
Ask one question at a time. Call verify_identity once for every answer. If an answer is wrong you may ask the same question again. If the result hint is day_month_swapped, ask them to say the month as a word (this is not a wrong answer) and call verify_identity again.
Never tell the customer an answer passed unless the result says verified.

Declining: if the customer does not want to answer, or asks what the call is about instead of answering, explain once that these questions protect their account and ask again. If they decline a second time (or ask a second time what it is about, or say a second time that they do not want to talk), thank them, say goodbye and call close_call (outcome not_verified, reason declined).
Human request: if they ask for a human/person, ask once whether you can help first. If they insist, call transfer_to_agent with queue general.
Before calling verify_identity, say nothing that claims the answer is right."""

VERIFY_FAILED_TASK = """The security check has failed after three wrong answers. Do NOT state any debt, amount, product or reason for the call. Tell the customer that you could not verify their identity and that they can use the Freya Bank mobile app or visit a branch. Then thank them, say goodbye and call close_call in the same message. Use no other tool."""

ACCOUNT_ERROR_TASK = """The account details could not be loaded (service error). Do not state any amount or product. Tell the customer you cannot access their account details right now and that they can use the Freya Bank mobile app. Thank them, say goodbye and call close_call in the same message. Use no other tool."""

NEGOTIATE_TASK = """The customer is verified. You have just told them about every late product (one sentence each) and asked whether they can pay today. Your job: agree a payment promise per product, or establish that a product gets none. Never call create_promise or add_note here; recording happens after the confirmed read-back.

PRODUCTS (handle them in exactly this order):
{{products_facts}}

DATES:
{{date_facts}}

RULES
A. The "today" question was asked once already. Never ask it again for each product. If the customer says yes to paying today, that is a promise of the full past-due amount dated today ({{today_iso}}) for the product(s) concerned. If they cannot pay (all of them) today, go product by product in the order above; each product starts at its attempt 1.
B. Persuasion (counted separately for each product). A flat refusal, a refusal to pay today without naming a date or amount, or a non-answer uses one attempt of that product:
   - Attempt 1: offer that product's attempt 1 offer (full amount, or the floor if the customer already said the full amount is too much) on the attempt 1 date shown.
   - Attempt 2 (late band only): offer the floor on that product's deadline.
   - When the product's attempts are used and the customer still refuses: stop for that product (no promise, reason refused). Never repeat an offer already refused. Move on to the next product.
C. A date or amount named by the customer is never a refusal. Dates: a promise date must be today or later, a business day, and not after that product's deadline (use the allowed dates list). Weekend/holiday not after the deadline: offer the next business day. Vague period ("next week", "end of the month", "when my salary comes"): ask once for the exact day; if still no exact day, propose the product's deadline. "Next <weekday>" = that weekday in the following calendar week; "this <weekday>" = in the current week (see Weekday words). Date after the deadline: say the latest date you can record is the deadline and offer it; refusing the deadline is a flat refusal (rule B). If the customer names one date for all products and it is after a product's deadline, that product goes on its own deadline (say so in the read-back) and the others keep the customer's date.
